-- TREAN AI Migration 4: authenticated context retrieval RPCs
create or replace function public.search_transcript_chunks(query_embedding public.vector,p_video_id uuid default null,p_match_count integer default 6) returns table(id uuid,video_id uuid,content text,start_seconds integer,end_seconds integer,similarity float) language sql stable security invoker set search_path='' as $$ select tc.id,tc.video_id,tc.content,tc.start_seconds,tc.end_seconds,1-(tc.embedding operator(public.<=>) query_embedding) as similarity from public.transcript_chunks tc join public.videos v on v.id=tc.video_id where tc.embedding is not null and v.user_id=(select auth.uid()) and (p_video_id is null or tc.video_id=p_video_id) order by tc.embedding operator(public.<=>) query_embedding limit greatest(1,least(p_match_count,12)); $$;
create or replace function public.search_knowledge_items(query_embedding public.vector,p_knowledge_ids uuid[] default null,p_match_count integer default 6) returns table(id uuid,video_id uuid,title text,content text,knowledge_type text,similarity float) language sql stable security invoker set search_path='' as $$ select ki.id,ki.video_id,ki.title,ki.content,ki.knowledge_type,1-(ki.embedding operator(public.<=>) query_embedding) as similarity from public.knowledge_items ki where ki.embedding is not null and ki.user_id=(select auth.uid()) and (p_knowledge_ids is null or cardinality(p_knowledge_ids)=0 or ki.id=any(p_knowledge_ids)) order by ki.embedding operator(public.<=>) query_embedding limit greatest(1,least(p_match_count,12)); $$;
revoke all on function public.search_transcript_chunks(public.vector,uuid,integer) from public,anon; revoke all on function public.search_knowledge_items(public.vector,uuid[],integer) from public,anon; grant execute on function public.search_transcript_chunks(public.vector,uuid,integer) to authenticated,service_role; grant execute on function public.search_knowledge_items(public.vector,uuid[],integer) to authenticated,service_role;